-- 003_orders_cache.sql
-- ============================================================
-- 003_orders_cache.sql
-- Phase D: cache Shopify orders locally so /cod-list and /fulfillment don't hit the Shopify API
-- on every page load. Webhook topics (orders/fulfillments) keep the cache fresh in near real-time.

create table if not exists shopify_orders_cache (
  id bigint primary key,                 -- shopify order id
  name text not null,
  order_number int,
  created_at timestamptz,
  financial_status text,
  fulfillment_status text,
  gateway text,
  payment_gateway_names text[],
  total_price numeric,
  currency text,
  country_code text,
  customer jsonb,
  shipping_address jsonb,
  is_cod boolean,
  raw jsonb,                              -- last full payload (for debugging)
  last_synced_at timestamptz not null default now()
);

create index if not exists shopify_orders_cache_created_idx
  on shopify_orders_cache (created_at desc);

create index if not exists shopify_orders_cache_unfulfilled_idx
  on shopify_orders_cache (fulfillment_status)
  where fulfillment_status is distinct from 'fulfilled';

create index if not exists shopify_orders_cache_is_cod_idx
  on shopify_orders_cache (is_cod)
  where is_cod;

alter table shopify_orders_cache enable row level security;

drop policy if exists shopify_orders_cache_read on shopify_orders_cache;
create policy shopify_orders_cache_read on shopify_orders_cache
  for select to authenticated using (true);

-- Writes go through service role (webhook handlers / backfill).

-- ============================================================
-- 004_order_ubex_links.sql
-- ============================================================
-- order_ubex_links: stores the resolved match between a Shopify order and its Ubex tracking ID.
-- Populated by the portal when the COD list / fulfillment pages build their Ubex lookup.
-- Consumed by the auto-sync cron (POST /api/sync/auto-fulfill) to detect when Ubex marks
-- a shipment as "Order Fulfilled" and then push the fulfillment + tracking link to Shopify.

create table if not exists order_ubex_links (
  shopify_order_id    bigint       primary key,
  shopify_order_name  text         not null,
  ubex_tracking       text         not null,
  last_ubex_status    text,
  auto_fulfilled_at   timestamptz,
  created_at          timestamptz  not null default now(),
  updated_at          timestamptz  not null default now()
);

-- Fast lookup by tracking id (cron iterates by order but useful for debugging).
create index if not exists order_ubex_links_tracking_idx
  on order_ubex_links (ubex_tracking);

-- Partial index: only un-fulfilled rows so the cron query stays O(pending) not O(all).
create index if not exists order_ubex_links_pending_idx
  on order_ubex_links (shopify_order_id)
  where auto_fulfilled_at is null;

-- RLS: service role can do everything; anon/authenticated cannot.
alter table order_ubex_links enable row level security;

drop policy if exists "service_role_all" on order_ubex_links;
create policy "service_role_all"
  on order_ubex_links
  for all
  to service_role
  using (true)
  with check (true);

-- ============================================================
-- 005_cron_run_log.sql
-- ============================================================
-- cron_run_log: one row per auto-fulfill cron execution.
-- Written by the auto-fulfill route at start (status='running') and
-- updated at end (status='success'|'error'). Read by the portal status panel.

create table if not exists cron_run_log (
  id            bigint        generated always as identity primary key,
  endpoint      text          not null default '/api/sync/auto-fulfill',
  dry_run       boolean       not null default false,
  status        text          not null,   -- 'running' | 'success' | 'error'
  checked       int,
  fulfilled     int,
  skipped       int,
  errors        int,
  error_detail  text,
  started_at    timestamptz   not null default now(),
  completed_at  timestamptz
);

-- Only keep the latest 500 rows to avoid unbounded growth.
create index if not exists cron_run_log_started_at_idx on cron_run_log (started_at desc);

alter table cron_run_log enable row level security;

drop policy if exists "service_role_all" on cron_run_log;
create policy "service_role_all"
  on cron_run_log for all to service_role
  using (true) with check (true);

