  add column if not exists can_be_sent int,
  add column if not exists products_short int,
  add column if not exists short_products jsonb not null default '[]'::jsonb;

-- ============================================================
-- 019_stock_alert_snapshots.sql
-- ============================================================
-- 019_stock_alert_snapshots.sql
-- Point-in-time low-stock/stockout counts captured when a human runs the
-- Stock Alerts scan. Mirrors stock_mismatch_snapshots so the dashboard tile
-- can show a recent count without re-running the full catalog scan.

create table if not exists stock_alert_snapshots (
  id uuid primary key default gen_random_uuid(),
  captured_at timestamptz not null default now(),
  captured_by uuid,
  critical_count int not null,
  warning_count int not null,
  critical_products jsonb not null default '[]'::jsonb
);

create index if not exists stock_alert_snapshots_captured_idx
  on stock_alert_snapshots (captured_at desc);

alter table stock_alert_snapshots enable row level security;

do $$ begin
  if not exists (
    select 1 from pg_policies
    where tablename = 'stock_alert_snapshots' and policyname = 'service_role_all'
  ) then
    create policy service_role_all on stock_alert_snapshots
      for all to service_role using (true) with check (true);
  end if;
end $$;

-- ============================================================
-- 020_merge_stock_modules.sql
-- ============================================================
-- 020_merge_stock_modules.sql
-- Stock analysis, Ubex Inventory and Stock Alerts were merged into the single "stock" module.
-- Rewrite per-user grants so nobody loses (or silently gains) access. Idempotent.
-- (The app also treats the legacy ids as granting "stock" at runtime, so applying this is optional but tidy.)
update profiles
set allowed_modules = (
  select coalesce(array_agg(distinct m), '{}')
  from unnest(
    array_remove(array_remove(array_remove(allowed_modules, 'stockAnalysis'), 'ubexInventory'), 'stockAlerts')
    || case
         when allowed_modules && array['stockAnalysis','ubexInventory','stockAlerts'] then array['stock']
         else '{}'::text[]
       end
  ) as m
)
where allowed_modules is not null
  and allowed_modules && array['stockAnalysis','ubexInventory','stockAlerts'];

-- ============================================================
-- 021_remove_cod_module.sql
-- ============================================================
-- 021_remove_cod_module.sql
-- The COD module was removed from the portal. Drop its id from per-user module grants.
-- Historical COD tables (cod_email_log, cod_settings keys) are intentionally kept for audit.
update profiles
set allowed_modules = array_remove(allowed_modules, 'cod')
where allowed_modules is not null and 'cod' = any(allowed_modules);

-- ============================================================
-- 022_signup_no_default_access.sql
-- ============================================================
-- 022_signup_no_default_access.sql
-- Security: a profile auto-created for a NEW auth user must start with NO module access.
-- Previously allowed_modules defaulted to NULL, which the app treats as "default members' access"
-- (Fulfillment + AWB). Combined with public sign-up being enabled in Supabase Auth, anyone holding the
-- (public) anon key could create an account and get that access.
-- Admin-created users are unaffected: createPortalUser() sets allowed_modules explicitly right after creation.
-- Existing profiles are not touched.
create or replace function handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email, full_name, allowed_modules)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'full_name', new.email), '{}'::text[])
  on conflict (id) do nothing;
  return new;
end;
$$;
